// Official registries used as neutral references.
//  - Java: reports generated by Mojang's own data generator (net.minecraft.data.Main
//    --reports) for the benchmark's Java version. Not redistributed by MCCB; regenerate
//    them (REPRODUCING.md) and point MCCB_JAVA_REPORTS at the `reports` folder.
//  - Bedrock: @minecraft/vanilla-data (Mojang, MIT), pinned in tools/package.json.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { REPO_ROOT, sha256File } from './archive.mjs';
const require = createRequire(import.meta.url);

export const JAVA_REFERENCE_VERSION = '26.3';
export const BEDROCK_REFERENCE_VERSION = '1.26.40';

export function javaReportsDir(version = JAVA_REFERENCE_VERSION) {
  return process.env.MCCB_JAVA_REPORTS || path.join(REPO_ROOT, '_staging', 'java-reports', version, 'reports');
}

let _java = null;
export function javaRegistry(version = JAVA_REFERENCE_VERSION) {
  if (_java) return _java;
  const dir = javaReportsDir(version);
  const blocksFile = path.join(dir, 'blocks.json');
  const regFile = path.join(dir, 'registries.json');
  const blocksJson = JSON.parse(fs.readFileSync(blocksFile, 'utf8'));
  const reg = JSON.parse(fs.readFileSync(regFile, 'utf8'));
  const blocks = new Map();
  for (const [name, b] of Object.entries(blocksJson)) {
    const def = (b.states || []).find((s) => s.default) || b.states?.[0];
    blocks.set(name, { properties: b.properties || {}, defaultProps: def?.properties || {} });
  }
  _java = {
    version,
    blocks,
    items: new Set(Object.keys(reg['minecraft:item'].entries)),
    entities: new Set(Object.keys(reg['minecraft:entity_type'].entries)),
    blockEntityTypes: new Set(Object.keys(reg['minecraft:block_entity_type']?.entries || {})),
    provenance: { source: `Mojang data generator reports, Java ${version}`, blocks_json_sha256: sha256File(blocksFile), registries_json_sha256: sha256File(regFile) },
  };
  return _java;
}

/** Full Java block state: registry default properties overlaid with the explicit ones. */
export function fullJavaState(name, props = {}) {
  const b = javaRegistry().blocks.get(name);
  if (!b) return { name, props: { ...props }, known: false };
  return { name, props: { ...b.defaultProps, ...props }, known: true };
}
export function javaStateKey(name, props = {}) {
  const s = fullJavaState(name, props);
  const keys = Object.keys(s.props).sort();
  return keys.length ? `${name}[${keys.map((k) => `${k}=${s.props[k]}`).join(',')}]` : name;
}

let _bedrock = null;
export function bedrockRegistry() {
  if (_bedrock) return _bedrock;
  // The package only exports ./lib/index.js; locate its folder from that entry point.
  const lib = path.resolve(path.dirname(require.resolve('@minecraft/vanilla-data')), '..');
  const pkg = JSON.parse(fs.readFileSync(path.join(lib, 'package.json'), 'utf8'));
  const read = (f) => fs.readFileSync(path.join(lib, 'lib', f), 'utf8');
  const ids = (txt) => new Set([...txt.matchAll(/= "(minecraft:[a-z0-9_]+)"/g)].map((m) => m[1]));
  const blockTxt = read('mojang-block.d.ts');
  const typeKeys = new Map();
  for (const m of blockTxt.matchAll(/export type (\w+)States = Pick<BlockStateSuperset, ([^>]+)>;/g)) {
    typeKeys.set(`${m[1]}States`, [...m[2].matchAll(/'([^']+)'/g)].map((x) => x[1]));
  }
  const stateKeys = new Map();
  const mapping = blockTxt.slice(blockTxt.indexOf('export type BlockStateMapping'));
  for (const m of mapping.matchAll(/'(minecraft:[a-z0-9_]+)': (\w+);/g)) stateKeys.set(m[1], typeKeys.get(m[2]) || []);
  _bedrock = {
    version: pkg.version,
    blocks: ids(blockTxt),
    blockStateKeys: stateKeys,
    items: ids(read('mojang-item.d.ts')),
    entities: ids(read('mojang-entity.d.ts')),
    provenance: { source: `@minecraft/vanilla-data ${pkg.version} (Mojang, MIT)` },
  };
  return _bedrock;
}

export function bedrockStateKey(name, states = {}) {
  const keys = Object.keys(states).sort();
  return keys.length ? `${name}[${keys.map((k) => `${k}=${states[k]}`).join(',')}]` : name;
}
